fn marvin_pront_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.lines_as("Marvin", args!["Whether it's schmoozing with a member of the opposite sex, or battling monsters, I gotta say, it's all about ^333399skills^000000."])?;
    ctx.next()?;
    ctx.mes("[Marvin]")?;
    if ctx.var("Sex").get()?.loosely_equals(&ctx.constant("SEX_MALE")?) {
        ctx.mes("I can't help you much when it comes to the subject of talking to attractive women such as myself, but I can tell you a little more about skills that help in battle.")?;
    } else {
        ctx.mes("I don't really have any advice for skills when it comes to talking to a cute guy, but I can let you in on what I know about skills that help in battle.")?;
    }
    ctx.next()?;
    ctx.lines_as("Marvin", args!["For most skills, the maximum level is level 10. It's easy to stress yourself out, since it takes so many points to completely master a skill. What skills should you choose?!"])?;
    ctx.next()?;
    ctx.lines_as("Marvin", args!["After all, if you spend too many skill points on one skill, you might not be able to learn another. That's right, there's a limit to the number of total skill points you can earn."])?;
    ctx.next()?;
    ctx.lines_as("Marvin", args!["But you know what? Not every skill is mastered at level 10. You can master some skills at only level 5. And even better, some skills are already mastered at level 1 or 2."])?;
    ctx.next()?;
    ctx.lines_as("Marvin", args!["So relax and plan ahead, so you can master all the skills that you really want to master the most. Also, don't just put skill points into anything. Remember to use your skill points wisely."])?;
    ctx.close_window()?;
    return Err(Stop::End);
}

