fn garnet_pront_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.lines_as(
        "Garnet",
        args![
            "Hello there~",
            "Are you interested in learning more about helping and supporting other people?"
        ],
    )?;
    ctx.next()?;
    ctx.lines_as("Garnet", args!["The Acolytes and Priests trained in this church can heal people, cure them of certain conditions, and even awaken the battle potential of other adventurers."])?;
    ctx.next()?;
    ctx.lines_as(
        "Garnet",
        args!["Go and ahead and ask if you have any questions about skills for Acolytes and Priests."],
    )?;
    'l1: loop {
        if !(true) {
            break 'l1;
        }
        'b1: {
            ctx.next()?;
            'b2: {
                let subject2 = Val::from(runtime::select_values(
                    ctx,
                    &[Val::from(
                        "About Heal:About Cure:About Increase AGI:About Angelus:About Blessing:About Warp Portal:End Conversation",
                    )],
                )?);
                let mut matched2 = false;
                let no_case2 = !subject2.loosely_equals(&Val::from(1))
                    && !subject2.loosely_equals(&Val::from(2))
                    && !subject2.loosely_equals(&Val::from(3))
                    && !subject2.loosely_equals(&Val::from(4))
                    && !subject2.loosely_equals(&Val::from(5))
                    && !subject2.loosely_equals(&Val::from(6))
                    && !subject2.loosely_equals(&Val::from(7));
                if !matched2 && subject2.loosely_equals(&Val::from(1)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.lines_as("Garnet", args!["You can recover your own HP with the ^6666CCHeal^000000 skill. Healing is one of the most important ways you can help your friends in battle."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["Even though our powers are usually used to heal others, you can actually use the ^6666CCHeal^000000 skill to hurt Undead monsters."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["Just remember to hold down the ^6666CCShift^000000 key when you use Cure or Heal on Undead monsters. Just be sure to hurt the monsters though, and don't use it to help monsters."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["Later, if you've learned ^6666CCHeal^000000 as an Acolyte, you can learn ^6666CCSanctuary^000000 if you become a Priest."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["Priests use ^6666CCSantuary^000000 to create an area which will restore the HP of you and your friends if you rest within the Sanctuary's area."])?;
                    break 'b1;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(2)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.lines_as("Garnet", args!["Once you reach ^6666CCLevel 2 Heal^000000 as an Acolyte, you can learn ^6666CCCure^000000, which can be used to treat abnormal statuses."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["This skill can be such a life saver, since almost every abnormal status can be cured with the Cure skill. Just remember that you need ^6666CCLevel 2 Heal^000000 before you can learn Cure."])?;
                    break 'b1;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(3)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.lines_as("Garnet", args!["Now, the ^6666CCIncrease AGI^000000 skill can be used on you or your friends. For a while your AGI stat is increased, making you attack faster and dodge monster attacks more easily."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["If you're an Acolyte that wants to learn ^6666CCIncrease AGI^000000, you need to learn ^6666CCLevel 3 Heal^000000 first."])?;
                    break 'b1;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(4)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.lines_as("Garnet", args!["You can use ^6666CCAngelus^000000 to increase your Defense, as well as the Defense of other party members. Remember though, you can only use ^6666CCAngelus^000000 on other people if they are in your party."])?;
                    ctx.next()?;
                    ctx.lines_as(
                        "Garnet",
                        args!["Before you can learn Angelus, you will need to have ^6666CCLevel 3 Divine Protection^000000."],
                    )?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["Also, if you keep learning Angelus, you'll eventually be able to learn ^6666CCKyrie Eleison^000000. That skill helps you evade initial attacks automatically."])?;
                    break 'b1;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(5)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.lines_as("Garnet", args!["^6666CCBlessing^000000 temporarily increases STR, DEX and INT. This skill will give you and your friends a great advantage in battle!"])?;
                    ctx.next()?;
                    ctx.lines_as(
                        "Garnet",
                        args!["Before you can learn Blessing, you must first learn ^6666CCLevel 5 Divine Protection^000000."],
                    )?;
                    break 'b1;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(6)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.lines_as("Garnet", args!["^6666CCWarp Portal^000000 is a pretty complex skill, and you need to know some other skills before you can learn it."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["First, you need to learn ^6666CCRuwach^000000 which lets you see invisible monsters. After Ruwach, you will need to learn the ^6666CCTeleport^000000 skill."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["Once you learn ^6666CCWarp Portal^000000, the level of the Warp Portal skill will determine how many warp destinations, or Warp Points, you can memorize."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["If you master the Warp Portal skill, you can have a maximum of 4 different Warp Points. But at least one Warp Point is designated as the Save Point that you've made with a Kafra Employee."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["Well, it's a bit of hassle, but if you want to make a certain place one of your Warp Points, you need to be physically there first. Then, type in ^6666CC/memo^000000 into the command prompt."])?;
                    ctx.next()?;
                    ctx.lines_as("Garnet", args!["Just so you know, you can't save a Warp Point inside of a dungeon. Oh, and don't forget, each time you make a Warp Portal, you must use 1 ^6666CCBlue Gemstone^000000 as a Catalyst."])?;
                    break 'b1;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(7)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.lines_as(
                        ctx.call(Function::StrCharInfo, vec![Val::from(0)])?,
                        args!["Alright, I've", "heard enough."],
                    )?;
                    ctx.close_window()?;
                    return Err(Stop::End);
                }
            }
        }
    }
    return Err(Stop::End);
}

